"""Build the generated files of the code design system.

Reads brand/tokens.json, illustrations/svg + anchors.json and product-ui/anchors.json.
Writes:
  design-system/src/tokens.css   CSS custom properties (one per token)
  design-system/src/tokens.js    the same values as window.VS.tokens
  design-system/src/assets.js    every public drawing (light SVG source + anchors) and
                                 the product UI element boxes, as window.VS.assets

The catalog and player load assets.js as a plain script, so both work from file://
and from GitHub Pages with no server and no build tool. Never edit the outputs by hand.

Run: python3 design-system/build.py
"""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
SRC = ROOT / "design-system" / "src"
HEAD = "/* GENERATED by design-system/build.py. Do not edit. */\n"


def tokens():
    raw = json.loads((ROOT / "brand" / "tokens.json").read_text())
    css, flat = [":root {"], {}
    for t in raw["color"]["tokens"]:
        v = t["value"]
        if isinstance(v, dict):
            for theme, hexv in v.items():
                css.append(f"  --{t['name']}-{theme}: {hexv};")
                flat[f"{t['name']}-{theme}"] = hexv
        elif not v.startswith("{"):
            css.append(f"  --{t['name']}: {v};")
            flat[t["name"]] = v
    for group in ("spacing", "radius", "duration", "easing", "stroke", "frame"):
        for t in raw[group]["tokens"]:
            css.append(f"  --{t['name']}: {t['value']};")
            flat[t["name"]] = t["value"]
    css.append(f"  --font-display: {raw['type']['families']['display']};")
    css.append(f"  --font-ui: {raw['type']['families']['ui']};")
    css.append("}")
    fonts = [f'@font-face {{ font-family: "{f["family"]}"; src: url("../../brand/{f["file"]}") format("woff2"); '
             f'font-weight: {f["weight"]}; font-style: {f["style"]}; }}' for f in raw["type"]["fonts"]]
    (SRC / "tokens.css").write_text(HEAD + "\n".join(fonts) + "\n" + "\n".join(css) + "\n")
    (SRC / "tokens.js").write_text(HEAD + "window.VS = window.VS || {};\nVS.tokens = " + json.dumps(flat, indent=1) + ";\n")
    return len(flat)


def assets():
    anchors = json.loads((ROOT / "illustrations" / "anchors.json").read_text())
    drawings = {}
    for name, a in anchors.items():
        svg = (ROOT / "illustrations" / "svg" / f"{name}-light.svg").read_text().strip()
        drawings[name] = {"svg": svg, "viewBox": a["viewBox"], "points": a["points"]}
    pui = json.loads((ROOT / "product-ui" / "anchors.json").read_text())
    # Pixel sizes of every captured image, so components can lay parts out before they load.
    from PIL import Image
    sizes = {}
    for f in sorted((ROOT / "product-ui").rglob("*.png")):
        with Image.open(f) as im:
            sizes[f.relative_to(ROOT / "product-ui").as_posix()] = list(im.size)
    body = {"drawings": drawings, "productUi": pui, "imageSizes": sizes}
    (SRC / "assets.js").write_text(HEAD + "window.VS = window.VS || {};\nVS.assets = " + json.dumps(body, separators=(",", ":")) + ";\n")
    return len(drawings)


if __name__ == "__main__":
    n_tok, n_draw = tokens(), assets()
    print(f"tokens: {n_tok}  drawings: {n_draw}  -> design-system/src")
